public struct CantoneseEntry {
    public var chinese: String
    public var jyutping: String
    public var english: String
    public var category: String
    public var tones: Data

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(chinese: String, jyutping: String, english: String, category: String, tones: Data) {
        self.chinese = chinese
        self.jyutping = jyutping
        self.english = english
        self.category = category
        self.tones = tones
    }
}



extension CantoneseEntry: Equatable, Hashable {
    public static func ==(lhs: CantoneseEntry, rhs: CantoneseEntry) -> Bool {
        if lhs.chinese != rhs.chinese {
            return false
        }
        if lhs.jyutping != rhs.jyutping {
            return false
        }
        if lhs.english != rhs.english {
            return false
        }
        if lhs.category != rhs.category {
            return false
        }
        if lhs.tones != rhs.tones {
            return false
        }
        return true
    }

    public func hash(into hasher: inout Hasher) {
        hasher.combine(chinese)
        hasher.combine(jyutping)
        hasher.combine(english)
        hasher.combine(category)
        hasher.combine(tones)
    }
}


